const expectedStatus = 404;
const expectedMessageIncludes = "Submission not found";

let responseJson = {};

try {
    responseJson = pm.response.json();
} catch (e) {
    console.log("Response không phải JSON:", pm.response.text());
    throw e;
}

pm.test("status code đúng", function () {
    pm.expect(pm.response.code).to.eql(expectedStatus);
});

pm.test("success đúng", function () {
    pm.expect(responseJson.success).to.eql(false);
});

pm.test("message đúng", function () {
    pm.expect(responseJson.message || "").to.include(expectedMessageIncludes);
});

pm.test("không có data thành công", function () {
    pm.expect(responseJson.data).to.be.undefined;
});

